  [17613] = { "Cura un alleato con magia oscura.", nil, 0xf7e48e1f, nil, "um" },
  [17615] = { "Colpisce un nemico con un dardo antimana. Per ogni punto di mana consumato, il bersaglio subisce $N1 danni.", nil, 0x5ae7b2cb, nil, "um" },
  [17616] = { "Fa esplodere un cadavere, infliggendo $N1 danni da ombra ai nemici vicini al cadavere.", nil, 0x9c96a028, nil, "um" },
  [17617] = { "+$N1 Armatura.", nil, 0x5e762e76, nil, "um" },
  [17618] = { "Evoca $N1 Risen Lackey per aiutare l'incantatore in battaglia per $D1.", nil, 0x0ac37867, nil, "um" },
  [17619] = { "Aumenta del $N1% gli effetti delle pozioni di cura e di mana su chi lo indossa.", nil, 0xe84771bc, nil, "um" },
  [17620] = { "Prosciuga $N1 salute a un nemico in $D1, trasferendola all'incantatore.", "$N1 salute prosciugata in $D1.", 0x48bccfdd, 0x1e299aef, "uu" },
  [17623] = { nil, "Permette a chi lo impugna di vedere gli spiriti di Caer Darrow. Funziona solo a Caer Darrow.", nil, 0xc5d47a45, "mu" },
  [17624] = { "Ti trasformi in pietra, diventando immune a tutti gli attacchi fisici e agli incantesimi per $D1, ma per tutto quel tempo non puoi attaccare, muoverti né lanciare incantesimi. Puoi beneficiare dell'effetto di un solo tonico alla volta.", "Immune ad attacchi e incantesimi. Impossibile attaccare, muoversi o usare incantesimi.", 0x7d8a1bc0, 0x16dc02b3, "uu" },
  [17625] = { "Aumenta la velocità di movimento del $N1% e rigenera $N2 salute ogni $N3 s.", "Velocità di movimento e rigenerazione della salute aumentate.", 0x389996ba, 0x7ab5007a, "uu" },
  [17626] = { "Aumenta la salute massima del personaggio di $N1 per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Salute aumentata di $N1.", 0x777139b8, 0x9cba3d80, "uu" },
  [17627] = { "Aumenta il mana massimo del personaggio di $N1 per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Mana aumentato di $N1.", 0xea66ca56, 0x63ed4136, "uu" },
  [17628] = { "Aumenta fino a un massimo di $N1 i danni inflitti da incantesimi ed effetti magici per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Danni magici aumentati fino a $N1.", 0x866d214b, 0x9d292bc3, "uu" },
  [17629] = { "Aumenta la resistenza a tutte le scuole di magia di $N1 per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte ed è cumulabile con tutti gli altri incantesimi e oggetti di resistenza.", "Resistenza a tutte le scuole di magia aumentata di $N1.", 0x0e8310bd, 0x1e7a7a6f, "uu" },
  [17630] = { "Colpisce un nemico con un dardo antimana. Per ogni punto di mana consumato, il bersaglio subisce $N1 danni.", nil, 0x5ae7b2cb, nil, "um" },
  [17631] = { "Infligge danni da ombra ai nemici vicini e li colpisce con dardi antimana, respingendoli indietro.", nil, 0x005a7d69, nil, "um" },
  [17633] = { "Aumenta la velocità di lancio d'incantesimi di un alleato del $N1% per $D1.", "Velocità di lancio d'incantesimi aumentata del $N1%.", 0x6b4d8c25, 0xb128184e, "uu" },
  [17639] = { "Riduce la probabilità d'impatto di un nemico del $N1% per $D1.", "Probabilità di colpire con gli attacchi ridotta del $N1%.", 0x03322dd8, 0x0a40f0d7, "uu" },
  [17650] = { "Riduce i danni inflitti del $N1%.", "Danni inflitti ridotti del $N1%.", 0x5eb0cb5a, 0x5eb0cb5a, "uu" },
  [17651] = { "Evoca $N1 Spectral Projection che combattono al posto dell'incantatore, che diventa invisibile e invulnerabile ma non può agire. Dopo $D1, queste apparizioni sacrificano la propria vita per curare l'incantatore, che riprende la battaglia.", "Invisibile, ma impossibilitato ad agire.\nImmune ad attacchi e incantesimi.", 0x9bdb93d5, 0x6d3858a8, "uu" },
  [17668] = { "Sfrutta il potere del fulmine per abbattere tutti i nemici intorno a te, infliggendo $N1 danni da natura.", nil, 0x2c25d731, nil, "um" },
  [17670] = { nil, "Permette l'acquisizione di Pietre del Flagello per conto dell'⟦Argent Dawn=Alba d'Argento⟧.", nil, 0xa21be432, "mu" },
  [17682] = { "Prosciuga fino a un massimo di $N1 mana a un nemico in $D1 e lo trasferisce all'incantatore.", "$N1 mana sottratto in $D1.", 0x55b7bb58, 0x84856b70, "uu" },
  [17684] = { "Aumenta i danni inflitti da incantesimi ed effetti di fuoco fino a un massimo di $N1.", nil, 0x6e8982e7, nil, "um" },
  [17685] = { "Infligge danni normali e $N1 danni aggiuntivi a un nemico e ai suoi alleati più vicini, colpendo fino a un massimo di $N2 bersagli.", nil, 0xb36a844f, nil, "um" },
  [17686] = { nil, "$N1 danni da natura subiti in $D1.", nil, 0x999464c0, "mu" },
  [17687] = { nil, "Velocità d'attacco aumentata del $N1%.", nil, 0x8859e2db, "mu" },
  [17691] = { nil, "Stordito.\nSarai rianimato automaticamente in $D1.", nil, 0x90c45b98, "mu" },
  [17692] = { nil, "$N1 danni da ombra subiti in $D1.", nil, 0x54e77887, "mu" },
  [17695] = { "Circonda l'incantatore con un'aura che riduce periodicamente la resistenza all'ombra dei nemici vicini di $N1. L'aura dura finché non viene annullata.", "Resistenza all'ombra dei nemici vicini ridotta periodicamente.", 0xb7aa9048, 0x744493fb, "uu" },
  [17697] = { nil, "Resistenza all'ombra ridotta di $N1.", nil, 0x47ba577e, "mu" },
