  [17740] = { "Avvolge l'incantatore con uno scudo protettivo che dura $D1 e assorbe fino a un massimo di $N2 danni fisici, prosciugando mana invece di salute. Prosciuga $N3 mana per ogni danno assorbito.", "Protezione contro danni fisici; perdita di mana invece che di salute.", 0xaf713b14, 0x16415ff7, "uu" },
  [17741] = { "Avvolge l'incantatore con uno scudo protettivo che dura $D1 e assorbe fino a un massimo di $N2 danni fisici, prosciugando mana invece di salute. Prosciuga $N3 mana per ogni danno assorbito.", "Protezione contro danni fisici; perdita di mana invece che di salute.", 0xaf713b14, 0x16415ff7, "uu" },
