  [17950] = { "Teletrasporta un nemico in uno dei 6 luoghi all'interno di Scholomance.", nil, 0xeebbd18b, nil, "um" },
  [17951] = { "Crea una Pietra del Fuoco che può essere usata per incantare la tua arma con il fuoco, aumentando la tua probabilità di critico con gli incantesimi del $N1% e i danni inflitti dai tuoi incantesimi di fuoco fino a un massimo di $N2.\n\nGli oggetti evocati scompaiono se si resta disconnessi per più di $N3 min.", nil, 0x4de9ee8f, nil, "um" },
  [17952] = { "Crea una Pietra del Fuoco Superiore che può essere usata per incantare la tua arma con il fuoco, aumentando la tua probabilità di critico con gli incantesimi del $N1% e i danni inflitti dai tuoi incantesimi di fuoco fino a un massimo di $N2.\n\nGli oggetti evocati scompaiono se si resta disconnessi per più di $N3 min.", nil, 0x64c011b1, nil, "um" },
  [17953] = { "Crea una Pietra del Fuoco Maggiore che può essere usata per incantare la tua arma con il fuoco, aumentando la tua probabilità di critico con gli incantesimi del $N1% e i danni inflitti dai tuoi incantesimi di fuoco fino a un massimo di $N2.\n\nGli oggetti evocati scompaiono se si resta disconnessi per più di $N3 min.", nil, 0x7c2e0041, nil, "um" },
